<template><AppShell><PageHeader title="Inventory Update" subtitle="Update packhouse stock levels for cement classifications."/><section class="mb-6 grid gap-4 md:grid-cols-3"><KpiCard label="Silo Alpha Capacity" value="82%" hint="Next delivery expected in 14 hours"/><KpiCard label="Packhouse Floor Space" value="64%" hint="High volume expected this weekend"/><KpiCard label="Loading Bay Efficiency" value="91%" hint="Peak performance window active"/></section><form class="space-y-6" @submit.prevent="submit"><section class="grid gap-5 lg:grid-cols-3"><div v-for="product in products" :key="product.id" class="card p-5"><div class="mb-5"><span class="rounded bg-navy px-3 py-1 text-xs font-bold uppercase tracking-widest text-white">{{ product.sku || 'Cement' }}</span><h2 class="mt-3 font-display text-2xl font-extrabold text-navy">{{ product.name }}</h2></div><button type="button" class="btn-secondary w-full" @click="selectProduct(product)">Select Product</button></div></section><section class="card grid gap-4 p-5 md:grid-cols-2"><FormSelect label="Warehouse" v-model="form.warehouse_id" :options="warehouses"/><FormSelect label="Product" v-model="form.product_id" :options="products"/><FormSelect label="Quantity Type" v-model="form.quantity_type" :options="quantityTypes"/><FormSelect label="Movement Type" v-model="form.movement_type" :options="movementTypes"/><FormInput label="Quantity" type="number" v-model="form.quantity"/><FormInput label="Remarks" v-model="form.remarks"/></section><section class="card flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between"><div><h2 class="font-display text-xl font-extrabold text-navy">Pre-Submission Check</h2><p class="max-w-2xl text-sm text-slate-600">Submitting confirms physical counts match digital inputs. Manual corrections over 5% trigger audit review.</p></div><button class="btn-primary">Submit Inventory Update</button></section></form></AppShell></template>
<script>import { Inertia } from '@inertiajs/inertia'; import AppShell from '../../Components/AppShell.vue'; import PageHeader from '../../Components/PageHeader.vue'; import KpiCard from '../../Components/KpiCard.vue'; import FormInput from '../../Components/FormInput.vue'; import FormSelect from '../../Components/FormSelect.vue'; export default{components:{AppShell,PageHeader,KpiCard,FormInput,FormSelect},props:{warehouses:Array,products:Array,quantityTypes:Array,movementTypes:Array},data(){return{form:{warehouse_id:this.warehouses[0]?this.warehouses[0].id:'',product_id:'',quantity_type:'palletized',movement_type:'adjustment',quantity:0,remarks:''}}},methods:{selectProduct(product){this.form.product_id=product.id},submit(){if(confirm('Confirm inventory update submission?')) Inertia.post('/inventory/update',this.form)}}}</script>